#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
A="$GSZ/routes/checkout.js"; B="$GSZ/views/product.ejs"
TS=$(date +%Y%m%d-%H%M%S)
echo "==> step182: restock waitlist (notify-me on OOS + email/WhatsApp on restock)"
for F in "$A" "$B"; do cp "$F" "$F.bak-step182-$TS"; done
echo "    backups: *.bak-step182-$TS"
restore(){ echo "!! restoring"; for F in "$A" "$B"; do cp "$F.bak-step182-$TS" "$F" 2>/dev/null||true; done; }
trap 'restore' ERR
echo "==> DB migration"
DBJS=$(mktemp /tmp/db182.XXXXXX.js); echo "" | base64 -d > "$DBJS"
( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" GSZ_ENV="$GSZ/.env" node "$DBJS" )
rm -f "$DBJS"
echo "==> applying file patches"
P=$(mktemp /tmp/p182.XXXXXX.js); echo "" | base64 -d > "$P"
NODE_PATH="$GSZ/node_modules" node "$P" "$GSZ"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$A" && echo "    checkout.js ok"
NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$B','utf8'),{filename:'$B'});console.log('    product.ejs ok')"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$P"; trap - ERR
echo ""
echo "==> step182 OK  On any out-of-stock plan, customers can tap 'Notify me when it's back' (email + optional WhatsApp). When that plan restocks, everyone waiting gets an email + WhatsApp once."
